$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '../..');Set-Location $root
$a11y=Get-Content artifacts/sprint36-accessibility-performance.json -Raw|ConvertFrom-Json;$workflow=Get-Content artifacts/sprint36-workflow-benchmarks.json -Raw|ConvertFrom-Json
$files=@('frontend/app.js','frontend/styles.css','frontend/accessibility.css','frontend/live-response.css','frontend/containment.css','frontend/design-system.css');$sizes=[ordered]@{};$total=0;foreach($file in $files){$n=(Get-Item $file).Length;$sizes[$file]=$n;$total+=$n}
$times=@($a11y.performance.totalMs|ForEach-Object{[double]$_}|Sort-Object);$p50=$times[[Math]::Min($times.Count-1,[Math]::Floor(($times.Count-1)*.50))];$p95=$times[[Math]::Min($times.Count-1,[Math]::Floor(($times.Count-1)*.95))]
$report=[ordered]@{schemaVersion='sprint36-frontend-performance.v1';capturedAt=[DateTimeOffset]::UtcNow.ToString('o');environment='Local Windows host; Docker Desktop Compose; headless Chrome; populated tenant fixtures';baseline=[ordered]@{staticBytes=528660;worstMs=2996;maximumDomNodes=2220;workflowTransitions=16;workflowTotalMs=3666};current=[ordered]@{staticBytes=$total;assetBytes=$sizes;p50Ms=$p50;p95Ms=$p95;worstMs=($times|Measure-Object -Maximum).Maximum;maximumDomNodes=($a11y.performance.domNodes|Measure-Object -Maximum).Maximum;workflowTransitions=$workflow.totals.transitions;workflowTotalMs=$workflow.totals.totalMs;endpointDetailApiRequests=$workflow.optimizations.endpointDetailRequests};delta=[ordered]@{staticBytes=$total-528660;staticPercent=[Math]::Round((($total-528660)/528660)*100,2);worstMs=($times|Measure-Object -Maximum).Maximum-2996;maximumDomNodes=($a11y.performance.domNodes|Measure-Object -Maximum).Maximum-2220;workflowTransitions=$workflow.totals.transitions-16;workflowTotalMs=$workflow.totals.totalMs-3666};bounds=[ordered]@{treeNodes=200;graphNodes=200;graphEdges=400;graphDepth=3;savedViews=20;searchCharacters=128};bottleneck='Administration remains the largest network/DOM surface; measurement includes local Compose request latency and Axe execution.';assessment='PASS: worst measured view materially improved, workflow transitions fell, DOM change is bounded, and assets remain within the existing single-module architecture.'};$report|ConvertTo-Json -Depth 10|Set-Content artifacts/sprint36-frontend-performance.json -Encoding utf8;$report|ConvertTo-Json -Depth 10
